.topbar { position: fixed; z-index: 1200; inset: 0 0 auto; height: 66px; padding: 0 24px; display: flex; align-items: center; justify-content: space-between; gap: 20px; background: rgba(11,16,14,.94); border-bottom: 1px solid var(--line); backdrop-filter: blur(14px); }
