.command-deck__metrics small { color: var(--ink-muted); font-size: 10px; line-height: 1.25; }

.controls { min-height: 70px; padding: 12px 0; display: flex; gap: 9px; align-items: center; border-bottom: 1px solid var(--line); }
.segmented { display: inline-flex; padding: 3px; border: 1px solid var(--line); border-radius: 8px; background: #0b110e; }
.segmented button { min-height: 36px; padding: 0 13px; border: 0; border-radius: 5px; background: transparent; color: var(--ink-muted); font-size: 12px; font-weight: 600; white-space: nowrap; }
.segmented button:hover { color: var(--ink); background: rgba(255,255,255,.035); }
.segmented button.is-active { background: var(--surface-high); color: var(--ink); box-shadow: inset 0 0 0 1px rgba(255,255,255,.04); }
.search-field, .select-field { height: 44px; display: flex; align-items: center; gap: 9px; border: 1px solid var(--line); background: var(--surface); border-radius: 8px; color: var(--ink-muted); }
.search-field { min-width: 220px; flex: 1; padding: 0 11px; }
