.button, .icon-button { border: 1px solid var(--line); background: var(--surface); display: inline-flex; align-items: center; justify-content: center; gap: 8px; border-radius: 8px; font-weight: 600; transition: background .15s, border-color .15s, transform .15s; }
.button { min-height: 44px; padding: 0 13px; font-size: 12px; }
.icon-button { width: 42px; height: 42px; padding: 0; }
.button:hover:not(:disabled), .icon-button:hover:not(:disabled) { background: var(--surface-high); border-color: var(--line-strong); }
.button:active:not(:disabled), .icon-button:active:not(:disabled) { transform: translateY(1px); }
.button:disabled { cursor: not-allowed; opacity: .4; }
.button--quiet { border-color: transparent; background: transparent; color: var(--ink-soft); }
.button--primary { color: #09110d; background: var(--mineral-bright); border-color: var(--mineral-bright); }
