.topbar__actions { display: flex; align-items: center; gap: 5px; }
.mobile-menu { display: none !important; }

main { padding: 0 24px 26px; max-width: 1800px; margin: 0 auto; }
.eyebrow { margin: 0 0 8px; color: var(--mineral); font: 600 10px/1.3 "Roboto Mono", monospace; letter-spacing: .14em; text-transform: uppercase; }
.command-deck { min-height: 214px; display: grid; grid-template-columns: minmax(0, 1.45fr) minmax(370px, .7fr); align-items: end; gap: 40px; padding: 42px 8px 30px; border-bottom: 1px solid var(--line); position: relative; overflow: hidden; }
.command-deck::before { content: ""; position: absolute; width: 580px; height: 220px; right: 1%; top: -120px; border: 1px solid rgba(137,191,165,.12); border-radius: 48%; transform: rotate(-8deg); box-shadow: 0 0 0 28px rgba(137,191,165,.025), 0 0 0 58px rgba(137,191,165,.018), 0 0 0 92px rgba(137,191,165,.012); pointer-events: none; }
.command-deck h1 { margin: 0; max-width: 720px; font: 600 clamp(31px, 4vw, 59px)/.98 "Manrope", sans-serif; letter-spacing: -.045em; }
