.map-shell, .earthquake-map { width: 100%; height: 100%; }
.earthquake-map { background: #0b1210; z-index: 1; }
.leaflet-container { font-family: "DM Sans", sans-serif; }
.leaflet-control-zoom { border: 1px solid var(--line-strong) !important; box-shadow: none !important; }
.leaflet-control-zoom a { width: 38px !important; height: 38px !important; line-height: 38px !important; background: #17211d !important; color: var(--ink) !important; border-color: var(--line) !important; }
.leaflet-control-attribution { background: rgba(11,16,14,.8) !important; color: #839087 !important; font-size: 8px !important; }
.leaflet-control-attribution a { color: #b5c4bb !important; }
.quake-marker-wrap { background: transparent !important; border: 0 !important; }
.quake-marker { --marker-color: var(--minor); position: absolute; left: calc(var(--marker-size) / -2); top: calc(var(--marker-size) / -2); width: var(--marker-size); height: var(--marker-size); display: grid; place-items: center; padding: 0; border-radius: 50%; border: 2px solid #08100d; background: color-mix(in srgb, var(--marker-color) 82%, #152019); color: #07100c; box-shadow: 0 0 0 1px var(--marker-color), 0 4px 15px rgba(0,0,0,.55); font: 700 10px "Roboto Mono", monospace; transition: transform .15s, box-shadow .15s; }
.quake-marker--moderate { --marker-color: var(--moderate); }
.quake-marker--strong { --marker-color: var(--strong); }
.quake-marker--major { --marker-color: var(--major); color: white; }
.quake-marker--unknown { --marker-color: var(--ink-muted); }
.quake-marker--intermediate { border-width: 4px; }
.quake-marker--deep { border-width: 6px; }
.quake-marker.is-hovered { transform: scale(1.18); z-index: 5; }
.quake-marker.is-selected { transform: scale(1.2); box-shadow: 0 0 0 3px #f6f2e6, 0 0 0 7px rgba(246,242,230,.18), 0 6px 20px rgba(0,0,0,.65); z-index: 6; }
.quake-cluster-wrap { background: transparent !important; }
.quake-cluster { width: 54px; height: 54px; padding: 0; border: 1px solid var(--mineral); border-radius: 50%; background: rgba(17,29,24,.92); color: var(--ink); box-shadow: 0 0 0 6px rgba(137,191,165,.11), 0 5px 20px rgba(0,0,0,.55); }
.quake-cluster span, .quake-cluster small { display: block; }
.quake-cluster span { font: 700 14px "Roboto Mono", monospace; }
.quake-cluster small { color: var(--mineral); font-size: 7px; text-transform: uppercase; letter-spacing: .08em; }
.quake-tooltip { max-width: 250px; padding: 8px 10px !important; border: 1px solid var(--line-strong) !important; border-radius: 6px !important; background: #111815 !important; color: var(--ink) !important; box-shadow: var(--shadow) !important; font-size: 11px !important; }
.quake-tooltip::before { border-top-color: #111815 !important; }
.quake-tooltip span { color: var(--ink-muted); }
.map-key { position: absolute; z-index: 500; left: 12px; bottom: 12px; max-width: calc(100% - 100px); min-height: 34px; padding: 8px 10px; display: flex; align-items: center; flex-wrap: wrap; gap: 10px; border: 1px solid rgba(69,86,78,.8); border-radius: 7px; background: rgba(11,16,14,.88); backdrop-filter: blur(10px); color: var(--ink-soft); font-size: 9px; }
.map-key span { display: inline-flex; align-items: center; gap: 5px; white-space: nowrap; }
.key-dot { width: 8px; height: 8px; border-radius: 50%; background: var(--minor); }
.key-dot--moderate { background: var(--moderate); }
.key-dot--strong { background: var(--strong); }
.key-dot--major { background: var(--major); }
.map-key__depth { color: var(--ink-muted); padding-left: 10px; border-left: 1px solid var(--line); }
.map-toolbar { position: absolute; z-index: 500; top: 12px; left: 12px; display: flex; border: 1px solid var(--line-strong); border-radius: 7px; overflow: hidden; box-shadow: 0 8px 22px rgba(0,0,0,.35); }
.map-toolbar button { min-height: 38px; padding: 0 11px; display: flex; align-items: center; gap: 7px; border: 0; border-right: 1px solid var(--line); background: rgba(17,24,21,.94); color: var(--ink-soft); font-size: 10px; font-weight: 600; }
.map-toolbar button:last-child { border-right: 0; }
.map-toolbar button:hover, .map-toolbar button.is-active { background: var(--surface-high); color: var(--mineral-bright); }

.stream { height: 100%; display: flex; flex-direction: column; }
.stream__header { min-height: 70px; padding: 14px 16px; border-bottom: 1px solid var(--line); display: flex; align-items: end; justify-content: space-between; gap: 15px; }
.stream__header .eyebrow { margin-bottom: 4px; }
.stream__header h2 { margin: 0; font: 600 15px "Manrope", sans-serif; }
.stream__header > p { max-width: 130px; margin: 0; color: var(--ink-muted); font-size: 9px; text-align: right; }
.stream__list { min-height: 0; overflow-y: auto; scrollbar-width: thin; scrollbar-color: var(--line-strong) transparent; }
.event-row { width: 100%; min-height: 94px; padding: 13px 10px 13px 14px; display: grid; grid-template-columns: 54px minmax(0, 1fr) auto 17px; align-items: center; gap: 11px; border: 0; border-bottom: 1px solid var(--line); background: transparent; text-align: left; position: relative; }
.event-row::before { content: ""; position: absolute; inset: 0 auto 0 0; width: 3px; background: transparent; }
.event-row:hover, .event-row.is-hovered { background: rgba(255,255,255,.025); }
.event-row.is-selected { background: rgba(137,191,165,.07); }
.event-row.is-selected::before { background: var(--mineral); }
.event-row__magnitude { width: 48px; height: 48px; border: 1px solid currentColor; border-radius: 50%; display: grid; align-content: center; justify-items: center; }
.event-row__magnitude strong { font: 600 15px/1 "Roboto Mono", monospace; }
.event-row__magnitude small { margin-top: 3px; font: 500 7px "Roboto Mono", monospace; opacity: .7; }
.magnitude-minor { color: var(--minor); }
.magnitude-moderate { color: var(--moderate); }
.magnitude-strong { color: var(--strong); }
.magnitude-major { color: var(--major); }
.event-row__place { display: -webkit-box; overflow: hidden; -webkit-line-clamp: 2; -webkit-box-orient: vertical; color: var(--ink); font: 600 12px/1.25 "Manrope", sans-serif; }
.event-row__meta { display: flex; flex-wrap: wrap; gap: 7px; margin-top: 6px; color: var(--ink-muted); font: 500 8.5px "Roboto Mono", monospace; }
.event-row__meta span + span::before, .event-row__meta time + span::before { content: "·"; margin-right: 7px; }
.event-row__status { min-height: 18px; margin-top: 7px; display: flex; flex-wrap: wrap; gap: 4px; }
.status-tag { min-height: 20px; padding: 2px 6px; display: inline-flex; align-items: center; gap: 4px; border: 1px solid var(--line); border-radius: 4px; color: var(--ink-soft); background: rgba(255,255,255,.02); font: 600 7.5px "Roboto Mono", monospace; text-transform: uppercase; }
.status-tag--green { border-color: #436c57; color: #a6d6bc; }
.status-tag--yellow { border-color: #766736; color: #e4cd77; }
.status-tag--orange { border-color: #764c35; color: #e69a67; }
.status-tag--red, .status-tag--tsunami { border-color: #78433e; color: #f09187; }
.event-row__assessment { display: block; max-width: 95px; text-align: right; }
.event-row__assessment span, .event-row__assessment small { display: block; }
.event-row__assessment span { color: var(--ink-soft); font-size: 9px; }
.event-row__assessment small { margin-top: 4px; color: var(--ink-muted); font-size: 8px; }
.event-row__chevron { color: var(--line-strong); }

.timeline { margin-top: 15px; border: 1px solid var(--line); border-radius: var(--radius); background: var(--surface); padding: 16px 18px 12px; }
.timeline__header { display: flex; justify-content: space-between; align-items: end; gap: 20px; margin-bottom: 10px; }
.timeline__header .eyebrow { margin-bottom: 3px; }
.timeline__header h2 { margin: 0; font: 600 15px "Manrope", sans-serif; }
.timeline__instruction { margin: 0; color: var(--ink-muted); font-size: 10px; }
.timeline__plot { position: relative; height: 152px; }
.timeline__plot svg { display: block; width: 100%; height: 100%; overflow: visible; }
.timeline__baseline { stroke: var(--line-strong); stroke-width: 1; vector-effect: non-scaling-stroke; }
.timeline__guide { stroke: var(--line); stroke-width: 1; stroke-dasharray: 3 7; vector-effect: non-scaling-stroke; }
.timeline__trace { fill: none; stroke: rgba(137,191,165,.28); stroke-width: 1.2; vector-effect: non-scaling-stroke; }
.timeline__point { fill: var(--minor); stroke: var(--surface); stroke-width: 2; vector-effect: non-scaling-stroke; cursor: pointer; transition: r .12s, opacity .12s; }
.timeline__point.magnitude-moderate { fill: var(--moderate); }
.timeline__point.magnitude-strong { fill: var(--strong); }
.timeline__point.magnitude-major { fill: var(--major); }
.timeline__point:hover, .timeline__point:focus, .timeline__point.is-selected { stroke: var(--ink); stroke-width: 3; outline: none; }
.timeline__cursor { stroke: var(--mineral-bright); stroke-width: 1.5; stroke-dasharray: 2 3; vector-effect: non-scaling-stroke; pointer-events: none; }
.timeline__scrubber { position: absolute; inset: 0; width: 100%; height: 100%; margin: 0; opacity: 0; cursor: ew-resize; }
.timeline__labels { display: flex; justify-content: space-between; padding: 3px 15px 0; color: var(--ink-muted); font: 500 8px "Roboto Mono", monospace; text-transform: uppercase; }
.timeline__empty { height: 90px; display: grid; place-items: center; color: var(--ink-muted); font-size: 12px; }

.detail { position: fixed; z-index: 1100; top: 66px; right: 0; bottom: 0; width: min(430px, 34vw); overflow-y: auto; background: #111815; border-left: 1px solid var(--line-strong); box-shadow: -20px 0 60px rgba(0,0,0,.3); animation: detail-in .22s ease-out; }
.detail__topbar { position: sticky; z-index: 3; top: 0; min-height: 58px; padding: 8px 13px; display: flex; align-items: center; justify-content: space-between; background: rgba(17,24,21,.94); border-bottom: 1px solid var(--line); backdrop-filter: blur(12px); color: var(--ink-muted); font: 600 9px "Roboto Mono", monospace; letter-spacing: .12em; text-transform: uppercase; }
.detail__actions { display: flex; gap: 5px; }
.detail__back { display: none; }
.detail__hero { padding: 27px 24px 22px; display: grid; grid-template-columns: 72px minmax(0,1fr); gap: 18px; align-items: center; border-bottom: 1px solid var(--line); }
.detail__mag { width: 72px; height: 72px; display: grid; place-content: center; justify-items: center; border: 2px solid currentColor; border-radius: 50%; }
.detail__mag span { font: 500 9px "Roboto Mono", monospace; }
.detail__mag strong { font: 600 26px "Roboto Mono", monospace; }
.detail__hero .eyebrow { margin-bottom: 7px; }
.detail__hero h2 { margin: 0; font: 600 clamp(18px, 1.5vw, 24px)/1.12 "Manrope", sans-serif; letter-spacing: -.025em; }
.detail__recency { margin: 8px 0 0; color: var(--ink-muted); font-size: 11px; }
.detail__notice { margin: 18px 20px 0; padding: 12px; display: flex; align-items: flex-start; gap: 9px; border: 1px solid #464b3d; border-radius: 7px; background: #1b1d17; color: #cec99f; }
.detail__notice svg { flex: 0 0 auto; }
.detail__notice p { margin: 0; font-size: 10px; line-height: 1.45; }
.detail__status-grid { margin: 18px 20px 0; display: grid; grid-template-columns: repeat(2, 1fr); border: 1px solid var(--line); border-radius: 7px; overflow: hidden; }
.detail__status-grid div { min-height: 70px; padding: 13px; border-right: 1px solid var(--line); border-bottom: 1px solid var(--line); }
.detail__status-grid div:nth-child(2n) { border-right: 0; }
.detail__status-grid div:nth-last-child(-n+2) { border-bottom: 0; }
.detail__status-grid span, .detail__status-grid strong { display: block; }
.detail__status-grid span { color: var(--ink-muted); font: 500 8px "Roboto Mono", monospace; text-transform: uppercase; letter-spacing: .06em; }
.detail__status-grid strong { margin-top: 6px; font: 600 15px "Manrope", sans-serif; }
.text-green { color: #a6d6bc; }.text-yellow { color: #e4cd77; }.text-orange { color: #e69a67; }.text-red { color: #f09187; }
.detail__flags { margin: 13px 20px 0; display: flex; flex-wrap: wrap; gap: 5px; }
.detail__section { margin: 22px 20px 0; padding-top: 18px; border-top: 1px solid var(--line); }
.detail__section h3 { margin: 0 0 12px; font: 600 11px "Roboto Mono", monospace; letter-spacing: .08em; text-transform: uppercase; }
.detail__list { margin: 0; }
.detail__list div { display: grid; grid-template-columns: minmax(110px,.65fr) 1.35fr; gap: 12px; padding: 9px 0; border-bottom: 1px solid rgba(44,57,51,.65); }
.detail__list dt { color: var(--ink-muted); font-size: 10px; }
.detail__list dd { margin: 0; color: var(--ink-soft); font: 500 10px/1.4 "Roboto Mono", monospace; text-align: right; overflow-wrap: anywhere; }
.detail__definition { color: var(--ink-muted); font-size: 9px; line-height: 1.5; }
.detail__usgs-link { margin: 24px 20px 0; min-height: 66px; padding: 11px 12px; display: grid; grid-template-columns: 20px 1fr 17px; align-items: center; gap: 10px; border: 1px solid var(--mineral); border-radius: 7px; color: var(--mineral-bright); text-decoration: none; }
.detail__usgs-link:hover { background: rgba(137,191,165,.07); }
.detail__usgs-link strong, .detail__usgs-link small { display: block; }
.detail__usgs-link strong { font-size: 11px; }
.detail__usgs-link small { margin-top: 4px; color: var(--ink-muted); font-size: 8px; line-height: 1.3; }
.detail__disclaimer { margin: 18px 20px 28px; color: var(--ink-muted); font-size: 9px; line-height: 1.5; }

.filter-overlay { position: fixed; z-index: 2000; inset: 0; display: flex; justify-content: flex-end; background: rgba(2,6,4,.68); backdrop-filter: blur(5px); }
.filter-panel { width: min(440px, 100%); height: 100%; display: flex; flex-direction: column; background: var(--surface); border-left: 1px solid var(--line-strong); box-shadow: var(--shadow); animation: detail-in .2s ease-out; }
.filter-panel__header { min-height: 70px; padding: 12px 17px 12px 22px; display: flex; align-items: center; justify-content: space-between; border-bottom: 1px solid var(--line); }
.filter-panel__header .eyebrow { margin-bottom: 3px; }
.filter-panel__header h2 { margin: 0; font: 600 20px "Manrope", sans-serif; }
.filter-panel__body { min-height: 0; flex: 1; overflow-y: auto; padding: 5px 22px 22px; }
.filter-group { margin: 0; padding: 20px 0; border: 0; border-bottom: 1px solid var(--line); }
.filter-group legend { width: 100%; color: var(--ink-soft); font-size: 11px; font-weight: 600; }
.filter-group legend strong { float: right; color: var(--mineral-bright); font: 600 11px "Roboto Mono", monospace; }
.filter-group > p { margin: 8px 0 13px; color: var(--ink-muted); font-size: 9px; line-height: 1.45; }
.filter-group input[type="range"] { width: 100%; height: 4px; margin: 20px 0 7px; accent-color: var(--mineral); }
.range-labels { display: flex; justify-content: space-between; color: var(--ink-muted); font: 500 8px "Roboto Mono", monospace; }
.chip-grid { display: flex; flex-wrap: wrap; gap: 6px; }
.filter-chip { min-height: 38px; padding: 0 11px; display: inline-flex; align-items: center; gap: 5px; border: 1px solid var(--line); border-radius: 6px; background: transparent; color: var(--ink-soft); font-size: 10px; }
.filter-chip:hover { border-color: var(--line-strong); background: rgba(255,255,255,.025); }
.filter-chip.is-active { background: var(--surface-high); border-color: currentColor; }
.alert-green { color: #a6d6bc; }.alert-yellow { color: #e4cd77; }.alert-orange { color: #e69a67; }.alert-red { color: #f09187; }.alert-none { color: var(--ink-soft); }
.segmented--wide { width: 100%; }
.segmented--wide button { flex: 1; }
.switch-row { min-height: 72px; display: grid; grid-template-columns: 1fr 48px; align-items: center; gap: 12px; border-bottom: 1px solid var(--line); position: relative; }
.switch-row strong, .switch-row small { display: block; }
.switch-row strong { color: var(--ink-soft); font-size: 11px; }
.switch-row small { margin-top: 4px; color: var(--ink-muted); font-size: 9px; }
.switch-row input { position: absolute; opacity: 0; }
.switch-row i { width: 44px; height: 24px; border-radius: 12px; background: var(--line); position: relative; transition: background .15s; }
.switch-row i::after { content: ""; position: absolute; width: 18px; height: 18px; top: 3px; left: 3px; border-radius: 50%; background: var(--ink-soft); transition: transform .15s, background .15s; }
.switch-row input:checked + i { background: var(--mineral); }
.switch-row input:checked + i::after { transform: translateX(20px); background: #07100c; }
.switch-row input:focus-visible + i { outline: 2px solid var(--focus); outline-offset: 3px; }
.filter-panel__footer { min-height: 74px; padding: 12px 18px; display: flex; gap: 9px; border-top: 1px solid var(--line); background: #0e1512; }
.filter-panel__footer .button { flex: 1; }

.loading-state { min-height: 540px; margin-top: 15px; display: grid; grid-template-columns: 1.3fr .7fr; border: 1px solid var(--line); border-radius: var(--radius); overflow: hidden; background: var(--surface); }
.loading-state__map { position: relative; overflow: hidden; background-color: #101714; background-image: linear-gradient(rgba(137,191,165,.04) 1px, transparent 1px), linear-gradient(90deg, rgba(137,191,165,.04) 1px, transparent 1px); background-size: 42px 42px; }
.loading-ripple { position: absolute; width: 80px; height: 80px; left: 32%; top: 42%; border: 1px solid var(--mineral); border-radius: 50%; animation: ripple 2s infinite; }
.loading-ripple--two { left: 67%; top: 25%; animation-delay: .8s; }
.loading-state__copy { display: flex; flex-direction: column; justify-content: center; padding: 35px; border-left: 1px solid var(--line); }
.loading-state__copy h2 { margin: 0; font: 600 25px/1.1 "Manrope", sans-serif; }
.loading-state__copy > p:not(.eyebrow) { color: var(--ink-muted); font-size: 12px; line-height: 1.55; }
.loading-lines { margin-top: 20px; display: grid; gap: 10px; }
.loading-lines i { display: block; height: 8px; border-radius: 4px; background: linear-gradient(90deg, var(--surface-high), #2c3933, var(--surface-high)); background-size: 200% 100%; animation: shimmer 1.8s infinite; }
.loading-lines i:nth-child(2) { width: 82%; }.loading-lines i:nth-child(3) { width: 61%; }
.fatal-state, .empty-state { min-height: 360px; display: flex; flex-direction: column; align-items: center; justify-content: center; padding: 35px; text-align: center; }
.fatal-state { margin-top: 15px; min-height: 520px; border: 1px solid var(--line); border-radius: var(--radius); background: var(--surface); }
.fatal-state > svg, .empty-state > svg { margin-bottom: 16px; color: var(--ink-muted); }
.fatal-state h2, .empty-state h2 { margin: 0; max-width: 480px; font: 600 23px/1.15 "Manrope", sans-serif; }
.fatal-state > p:not(.eyebrow), .empty-state > p:not(.eyebrow) { max-width: 490px; color: var(--ink-muted); font-size: 12px; line-height: 1.55; }
.fatal-state .button, .empty-state .button { margin-top: 10px; }
.mobile-view-switcher { display: none; }
.toast { position: fixed; z-index: 3000; left: 50%; bottom: 24px; transform: translateX(-50%); min-height: 44px; padding: 0 15px; display: flex; align-items: center; gap: 8px; border: 1px solid var(--line-strong); border-radius: 8px; background: var(--surface-high); box-shadow: var(--shadow); font-size: 11px; }
.site-footer { min-height: 58px; padding: 15px 24px; display: flex; align-items: center; justify-content: space-between; gap: 30px; border-top: 1px solid var(--line); color: var(--ink-muted); font-size: 9px; line-height: 1.4; }
.site-footer a { color: var(--ink-soft); }
.spin { animation: spin .8s linear infinite; }

@keyframes pulse { 50% { opacity: .35; transform: scale(.75); } }
@keyframes spin { to { transform: rotate(360deg); } }
@keyframes detail-in { from { transform: translateX(24px); opacity: 0; } }
@keyframes ripple { from { transform: scale(.2); opacity: 1; } to { transform: scale(4); opacity: 0; } }
@keyframes shimmer { to { background-position: -200% 0; } }

@media (max-width: 1180px) {
  .app.has-detail { padding-right: 390px; }
  .detail { width: 390px; }
  .command-deck { grid-template-columns: 1.1fr .9fr; }
  .atlas { grid-template-columns: minmax(0, 1.25fr) minmax(330px, .75fr); }
  .event-row__assessment { display: none; }
  .event-row { grid-template-columns: 52px minmax(0,1fr) 17px; }
  .topbar__status { display: none; }
}

@media (max-width: 900px) {
  main { padding-inline: 16px; }
  .topbar { padding-inline: 16px; }
  .command-deck { grid-template-columns: 1fr; min-height: 0; gap: 26px; padding-top: 32px; }
  .command-deck__metrics { max-width: 600px; }
  .controls { flex-wrap: wrap; }
  .time-selector { order: 0; width: 100%; }
  .time-selector button { flex: 1; }
  .search-field { order: 1; }
  .select-field { order: 2; }
  .button--filter { order: 3; }
  .button--reset { order: 4; }
  .atlas { height: 620px; grid-template-columns: minmax(0, 1.1fr) minmax(310px, .9fr); }
  .map-key__depth { display: none !important; }
}

@media (max-width: 760px) {
  .app, .app.has-detail { padding-right: 0; padding-top: 58px; }
  .topbar { height: 58px; }
  .brand { min-width: 0; }
  .brand__mark { width: 31px; height: 31px; }
  .brand small { display: none; }
  .topbar__actions .button { width: 42px; padding: 0; }
  .topbar__actions .button span { display: none; }
  .mobile-menu { display: inline-flex !important; }
  main { padding: 0 12px 20px; }
  .command-deck { padding: 28px 2px 22px; }
  .command-deck::before { right: -260px; }
  .command-deck h1 { font-size: 35px; }
  .lead-event { width: 100%; grid-template-columns: 48px minmax(0,1fr) 18px; }
  .lead-event__mag { width: 48px; height: 48px; }
  .command-deck__metrics { width: 100%; }
  .command-deck__metrics > div { padding: 0 10px; }
  .command-deck__metrics > div:first-child { border-left: 0; padding-left: 0; }
  .command-deck__metrics strong { font-size: 25px; }
  .controls { position: relative; gap: 7px; padding-block: 10px; }
  .search-field { flex-basis: calc(100% - 51px); }
  .select-field { width: calc(100% - 53px); }
  .controls > .button--filter { width: 46px; padding: 0; font-size: 0; }
  .controls > .button--filter span { position: absolute; top: -5px; right: -5px; font-size: 9px; }
  .controls > .button--reset { width: 46px; padding: 0; font-size: 0; border: 1px solid var(--line); }
  .data-banner { align-items: flex-start; }
  .data-banner button { align-self: center; }
  .mobile-view-switcher { display: flex; width: 100%; margin: 12px 0 0; }
  .mobile-view-switcher button { flex: 1; }
  .atlas { height: min(590px, calc(100dvh - 150px)); min-height: 480px; display: block; margin-top: 8px; }
  .atlas__map, .atlas__stream { width: 100%; height: 100%; border: 0; }
  .atlas.show-map .atlas__stream, .atlas.show-stream .atlas__map { display: none; }
  .stream__header { min-height: 65px; }
  .event-row { min-height: 96px; padding-left: 11px; }
  .timeline { padding-inline: 11px; }
  .timeline__header { align-items: flex-start; }
  .timeline__instruction { max-width: 150px; text-align: right; }
  .timeline__plot { height: 130px; overflow: hidden; }
  .map-key { right: 62px; max-width: none; gap: 7px; }
  .map-key span { font-size: 0; gap: 0; }
  .key-dot { width: 10px; height: 10px; }
  .detail { z-index: 1500; top: 0; width: 100%; animation: detail-in .2s ease-out; }
  .detail__topbar { min-height: 58px; }
  .detail__back { display: inline-flex; }
  .detail__desktop-close { display: none; }
  .detail__hero { padding-inline: 18px; }
  .detail__notice, .detail__status-grid, .detail__flags, .detail__section, .detail__usgs-link { margin-left: 16px; margin-right: 16px; }
  .filter-panel__body { padding-inline: 18px; }
  .loading-state { min-height: 500px; grid-template-columns: 1fr; grid-template-rows: 1fr auto; }
  .loading-state__copy { padding: 22px; border-left: 0; border-top: 1px solid var(--line); }
  .loading-state__copy h2 { font-size: 20px; }
  .site-footer { padding-inline: 16px; display: block; }
  .site-footer span { display: block; margin: 4px 0; }
}

@media (max-width: 420px) {
  .topbar__actions .button:first-child { display: none; }
  .brand strong { font-size: 13px; }
  .command-deck h1 { font-size: 31px; }
  .command-deck__metrics small { font-size: 8px; }
  .time-selector button { padding-inline: 7px; font-size: 10px; }
  .event-row__meta span:last-child { display: none; }
  .event-row__status .status-tag:not(.status-tag--tsunami):not(.status-tag--red):not(.status-tag--orange) { display: none; }
  .map-toolbar button { padding-inline: 9px; font-size: 9px; }
  .detail__hero { grid-template-columns: 62px minmax(0,1fr); gap: 13px; }
  .detail__mag { width: 62px; height: 62px; }
}

@media (prefers-reduced-motion: reduce) {
  *, *::before, *::after { scroll-behavior: auto !important; animation-duration: .01ms !important; animation-iteration-count: 1 !important; transition-duration: .01ms !important; }
}

@media (forced-colors: active) {
  .quake-marker, .event-row__magnitude, .lead-event__mag, .detail__mag { forced-color-adjust: none; background: Canvas; color: CanvasText; border-color: CanvasText; }
  .timeline__point { fill: CanvasText; stroke: Canvas; }
  .event-row.is-selected { outline: 2px solid Highlight; outline-offset: -3px; }
}

