:root {
  color-scheme: dark;
  --ink: #f2f0e8;
  --ink-soft: #b7bdb4;
  --ink-muted: #7e8b82;
  --ground: #0b100e;
  --surface: #111815;
  --surface-raised: #17211d;
  --surface-high: #202c27;
  --line: #2c3933;
  --line-strong: #45564e;
  --mineral: #89bfa5;
  --mineral-bright: #b8dec9;
  --minor: #9eb6aa;
  --moderate: #f0bf68;
  --strong: #e97e52;
  --major: #e34f48;
  --danger: #f1786d;
  --focus: #d9f4e5;
  --radius: 10px;
  --shadow: 0 22px 70px rgba(0, 0, 0, .42);
  font-family: "DM Sans", system-ui, sans-serif;
  background: var(--ground);
  color: var(--ink);
  font-synthesis: none;
  text-rendering: optimizeLegibility;
}

* { box-sizing: border-box; }
html { background: var(--ground); scroll-behavior: smooth; }
body { margin: 0; min-width: 320px; min-height: 100vh; background: var(--ground); }
button, input, select { font: inherit; }
button, select, input[type="range"], input[type="checkbox"] { cursor: pointer; }
button { color: inherit; }
a { color: inherit; }
:focus-visible { outline: 2px solid var(--focus); outline-offset: 3px; }
::selection { background: var(--mineral); color: #07100c; }

body::before {
  content: "";
  position: fixed;
  inset: 0;
  pointer-events: none;
  opacity: .16;
  z-index: 10000;
  background-image: url("data:image/svg+xml,%3Csvg viewBox='0 0 160 160' xmlns='http://www.w3.org/2000/svg'%3E%3Cfilter id='n'%3E%3CfeTurbulence type='fractalNoise' baseFrequency='.85' numOctaves='2' stitchTiles='stitch'/%3E%3C/filter%3E%3Crect width='100%25' height='100%25' filter='url(%23n)' opacity='.16'/%3E%3C/svg%3E");
  mix-blend-mode: soft-light;
}

.sr-only { position: absolute !important; width: 1px; height: 1px; padding: 0; margin: -1px; overflow: hidden; clip: rect(0,0,0,0); white-space: nowrap; border: 0; }
.skip-link { position: fixed; top: 8px; left: 8px; transform: translateY(-150%); z-index: 10001; padding: 10px 14px; background: var(--focus); color: #08110d; border-radius: 6px; font-weight: 700; }
.skip-link:focus { transform: translateY(0); }

.app { min-height: 100vh; padding-top: 66px; transition: padding-right .22s ease; }
.app.has-detail { padding-right: min(430px, 34vw); }
.topbar { position: fixed; z-index: 1200; inset: 0 0 auto; height: 66px; padding: 0 24px; display: flex; align-items: center; justify-content: space-between; gap: 20px; background: rgba(11,16,14,.94); border-bottom: 1px solid var(--line); backdrop-filter: blur(14px); }
.brand { display: inline-flex; align-items: center; gap: 11px; text-decoration: none; min-width: 190px; }
.brand__mark { width: 34px; height: 34px; display: grid; place-content: center; gap: 3px; border: 1px solid var(--line-strong); border-radius: 50%; overflow: hidden; }
.brand__mark i { display: block; width: 22px; height: 1px; background: var(--mineral-bright); transform-origin: center; }
.brand__mark i:nth-child(1) { transform: rotate(-12deg) scaleX(.75); }
.brand__mark i:nth-child(2) { transform: rotate(8deg); }
.brand__mark i:nth-child(3) { transform: rotate(-5deg) scaleX(.55); }
.brand strong { display: block; font: 700 15px/1 "Manrope", sans-serif; letter-spacing: .19em; }
.brand small { display: block; margin-top: 5px; color: var(--ink-muted); font: 500 8px/1 "Roboto Mono", monospace; letter-spacing: .16em; }
.topbar__status { display: flex; align-items: center; gap: 9px; color: var(--ink-soft); font: 500 11px/1 "Roboto Mono", monospace; text-transform: uppercase; letter-spacing: .06em; }
