.brand__mark i { display: block; width: 22px; height: 1px; background: var(--mineral-bright); transform-origin: center; }
.brand__mark i:nth-child(1) { transform: rotate(-12deg) scaleX(.75); }
.brand__mark i:nth-child(2) { transform: rotate(8deg); }
.brand__mark i:nth-child(3) { transform: rotate(-5deg) scaleX(.55); }
.brand strong { display: block; font: 700 15px/1 "Manrope", sans-serif; letter-spacing: .19em; }
