.segmented button:hover { color: var(--ink); background: rgba(255,255,255,.035); }
.segmented button.is-active { background: var(--surface-high); color: var(--ink); box-shadow: inset 0 0 0 1px rgba(255,255,255,.04); }
.search-field, .select-field { height: 44px; display: flex; align-items: center; gap: 9px; border: 1px solid var(--line); background: var(--surface); border-radius: 8px; color: var(--ink-muted); }
.search-field { min-width: 220px; flex: 1; padding: 0 11px; }
.search-field:focus-within, .select-field:focus-within { border-color: var(--mineral); box-shadow: 0 0 0 3px rgba(137,191,165,.08); }
.search-field input { min-width: 0; flex: 1; border: 0; outline: 0; color: var(--ink); background: transparent; font-size: 13px; }
.search-field input::placeholder { color: var(--ink-muted); }
.search-field button { width: 30px; height: 30px; display: grid; place-items: center; border: 0; background: transparent; color: var(--ink-muted); border-radius: 50%; }
.select-field { width: 176px; padding: 0 10px; position: relative; }
.select-field select { flex: 1; min-width: 0; appearance: none; border: 0; outline: 0; background: transparent; color: var(--ink-soft); font-size: 12px; }
.select-field > svg:last-child { pointer-events: none; }
.button, .icon-button { border: 1px solid var(--line); background: var(--surface); display: inline-flex; align-items: center; justify-content: center; gap: 8px; border-radius: 8px; font-weight: 600; transition: background .15s, border-color .15s, transform .15s; }
