import { useEffect, useMemo, useState } from 'react'
import type { Dispatch, SetStateAction } from 'react'
import { AlertCircle, Check, ChevronDown, Crosshair, Filter, Globe2, LocateFixed, Menu, RefreshCw, RotateCcw, Search, Share2, SlidersHorizontal, WifiOff, X } from 'lucide-react'
import { EarthquakeMap } from './components/EarthquakeMap'
import { EventDetail } from './components/EventDetail'
import { EventStream } from './components/EventStream'
import { SeismicTimeline } from './components/SeismicTimeline'
import { useEarthquakeData } from './hooks/useEarthquakeData'
import {
  AREA_LABELS,
  DEFAULT_FILTERS,
  RANGE_LABELS,
  filterAndSort,
  filterCount,
  filtersFromUrl,
  formatMagnitude,
  formatRelativeTime,
  magnitudeLabel,
  significanceLabel,
  writeUrlState,
} from './lib/earthquakes'
import type { AlertLevel, FilterState, GeoArea, MapBounds, SortMode, TimeRange } from './types/earthquake'
import './styles.css'

const initialUrlState = filtersFromUrl()
const RANGE_OPTIONS: TimeRange[] = ['hour', 'day', 'week', 'month']
const ALERT_OPTIONS: { value: AlertLevel; label: string }[] = [
  { value: 'green', label: 'Green' }, { value: 'yellow', label: 'Yellow' },
  { value: 'orange', label: 'Orange' }, { value: 'red', label: 'Red' }, { value: 'none', label: 'None' },
]
const AREA_OPTIONS: GeoArea[] = ['world', 'americas', 'pacific', 'asia', 'europe', 'africa', 'oceania', 'viewport']
const SORT_OPTIONS: { value: SortMode; label: string }[] = [
  { value: 'significance', label: 'Most significant' },
  { value: 'newest', label: 'Newest first' },
  { value: 'magnitude', label: 'Highest magnitude' },
  { value: 'depth', label: 'Deepest first' },
  { value: 'felt', label: 'Most felt reports' },
]

function LoadingSkeleton() {
  return (
    <div className="loading-state" aria-label="Loading live USGS earthquake data" role="status">
      <div className="loading-state__map"><span className="loading-ripple" /><span className="loading-ripple loading-ripple--two" /></div>
      <div className="loading-state__copy">
        <p className="eyebrow">Connecting to USGS</p>
        <h2>Reading the latest global activity</h2>
        <p>Preparing map positions, magnitudes, depths, and event times.</p>
        <div className="loading-lines"><i /><i /><i /></div>
      </div>
    </div>
  )
}

function FilterPanel({ filters, setFilters, onReset, count, onClose }: {
  filters: FilterState
  setFilters: Dispatch<SetStateAction<FilterState>>
  onReset: () => void
  count: number
  onClose: () => void
}) {
  const toggleAlert = (alert: AlertLevel) => setFilters((current) => ({
    ...current,
    alerts: current.alerts.includes(alert) ? current.alerts.filter((item) => item !== alert) : [...current.alerts, alert],
  }))
  return (
    <div className="filter-panel" aria-label="Advanced earthquake filters">
      <header className="filter-panel__header">
        <div><p className="eyebrow">Refine the field</p><h2>Filters</h2></div>
        <button className="icon-button" type="button" onClick={onClose} aria-label="Close filters"><X size={20} /></button>
      </header>
      <div className="filter-panel__body">
        <fieldset className="filter-group">
          <legend>Minimum magnitude <strong>{filters.minMagnitude.toFixed(1)}+</strong></legend>
          <input type="range" min="0" max="7" step="0.5" value={filters.minMagnitude} onChange={(event) => setFilters((current) => ({ ...current, minMagnitude: Number(event.target.value) }))} />
          <div className="range-labels"><span>All</span><span>4 notable</span><span>7 major</span></div>
          <p>Magnitude measures energy released. It does not by itself predict damage.</p>
        </fieldset>
        <fieldset className="filter-group">
          <legend>Maximum depth <strong>{filters.maxDepth >= 700 ? 'Any' : `${filters.maxDepth} km`}</strong></legend>
          <input type="range" min="10" max="700" step="10" value={filters.maxDepth} onChange={(event) => setFilters((current) => ({ ...current, maxDepth: Number(event.target.value) }))} />
          <div className="range-labels"><span>Shallow</span><span>300 km</span><span>Any depth</span></div>
          <p>Shallow earthquakes often produce stronger surface shaking nearby.</p>
        </fieldset>
        <fieldset className="filter-group">
          <legend>Alert level</legend>
          <p>USGS alert levels estimate potential impact after an event.</p>
          <div className="chip-grid">
            {ALERT_OPTIONS.map(({ value, label }) => <button key={value} type="button" className={`filter-chip alert-${value}${filters.alerts.includes(value) ? ' is-active' : ''}`} aria-pressed={filters.alerts.includes(value)} onClick={() => toggleAlert(value)}>{filters.alerts.includes(value) && <Check size={14} />} {label}</button>)}
          </div>
        </fieldset>
        <fieldset className="filter-group">
          <legend>Review status</legend>
          <div className="segmented segmented--wide">
            {(['all', 'reviewed', 'automatic'] as const).map((status) => <button key={status} type="button" className={filters.reviewStatus === status ? 'is-active' : ''} aria-pressed={filters.reviewStatus === status} onClick={() => setFilters((current) => ({ ...current, reviewStatus: status }))}>{status === 'all' ? 'Any' : status[0].toUpperCase() + status.slice(1)}</button>)}
          </div>
        </fieldset>
        <label className="switch-row">
          <span><strong>Tsunami flag only</strong><small>Events marked by USGS as tsunami-related</small></span>
          <input type="checkbox" checked={filters.tsunamiOnly} onChange={(event) => setFilters((current) => ({ ...current, tsunamiOnly: event.target.checked }))} />
          <i aria-hidden="true" />
        </label>
      </div>
      <footer className="filter-panel__footer">
        <button className="button button--ghost" type="button" onClick={onReset} disabled={count === 0}><RotateCcw size={17} /> Reset all</button>
        <button className="button button--primary" type="button" onClick={onClose}>Show results</button>
      </footer>
    </div>
  )
}

export default function App() {
  const [filters, setFilters] = useState<FilterState>(initialUrlState.filters)
  const [selectedId, setSelectedId] = useState<string | null>(initialUrlState.selectedId)
  const [hoveredId, setHoveredId] = useState<string | null>(null)
  const [bounds, setBounds] = useState<MapBounds | null>(null)
  const [filtersOpen, setFiltersOpen] = useState(false)
  const [mobileView, setMobileView] = useState<'map' | 'stream'>('map')
  const [fitNonce, setFitNonce] = useState(0)
  const [toast, setToast] = useState<string | null>(null)
  const { events, generatedAt, receivedAt, loading, refreshing, error, refresh } = useEarthquakeData(filters.timeRange)
  const filteredEvents = useMemo(() => filterAndSort(events, filters, bounds), [events, filters, bounds])
  const selected = selectedId ? events.find((event) => event.id === selectedId) ?? null : null
  const strongest = useMemo(() => filteredEvents.reduce<(typeof filteredEvents)[number] | null>((best, event) => !best || (event.magnitude ?? -1) > (best.magnitude ?? -1) ? event : best, null), [filteredEvents])
  const activeCount = filterCount(filters)
  const isOffline = typeof navigator !== 'undefined' && !navigator.onLine
  const dataAge = receivedAt ? Date.now() - receivedAt : 0
  const isStale = dataAge > 15 * 60_000

  useEffect(() => writeUrlState(filters, selectedId), [filters, selectedId])
  useEffect(() => {
    if (!toast) return
    const timeout = window.setTimeout(() => setToast(null), 2400)
    return () => window.clearTimeout(timeout)
  }, [toast])
  useEffect(() => {
    const onKeyDown = (event: KeyboardEvent) => {
      if (event.key === 'Escape') {
        if (filtersOpen) setFiltersOpen(false)
        else if (selectedId) setSelectedId(null)
      }
    }
    window.addEventListener('keydown', onKeyDown)
    return () => window.removeEventListener('keydown', onKeyDown)
  }, [filtersOpen, selectedId])

  const resetFilters = () => setFilters((current) => ({ ...DEFAULT_FILTERS, timeRange: current.timeRange }))
  const selectEvent = (id: string) => {
    setSelectedId(id)
    if (window.innerWidth < 760) setMobileView('map')
  }
  const share = async () => {
    const url = window.location.href
    try {
      if (navigator.share && window.innerWidth < 760) await navigator.share({ title: selected ? selected.title : 'Tectonic earthquake view', url })
      else await navigator.clipboard.writeText(url)
      setToast(navigator.share && window.innerWidth < 760 ? 'Share sheet opened' : 'Link copied to clipboard')
    } catch (shareError) {
      if ((shareError as DOMException)?.name !== 'AbortError') setToast('Copy this page address to share the view')
    }
  }

  return (
    <div className={`app${selected ? ' has-detail' : ''}`}>
      <a className="skip-link" href="#event-stream">Skip to event stream</a>
      <header className="topbar">
        <a href="/" className="brand" aria-label="Tectonic earthquake observatory home">
          <span className="brand__mark" aria-hidden="true"><i /><i /><i /></span>
          <span><strong>TECTONIC</strong><small>LIVE EARTH OBSERVATORY</small></span>
        </a>
        <div className="topbar__status" role="status" aria-live="polite">
          <span className={`live-indicator${error ? ' is-error' : refreshing ? ' is-refreshing' : ''}`} />
          <span>{error ? 'Live connection interrupted' : refreshing ? 'Refreshing USGS data' : `USGS · updated ${generatedAt ? formatRelativeTime(generatedAt) : 'pending'}`}</span>
        </div>
        <div className="topbar__actions">
          <button className="button button--quiet" type="button" onClick={() => void share()}><Share2 size={17} /><span>Share view</span></button>
          <button className="button button--quiet" type="button" onClick={() => void refresh()} disabled={refreshing} aria-label={refreshing ? 'Refreshing earthquake data' : 'Refresh earthquake data'}><RefreshCw className={refreshing ? 'spin' : ''} size={17} /><span>Refresh</span></button>
          <button className="icon-button mobile-menu" type="button" onClick={() => setFiltersOpen(true)} aria-label="Open filters"><Menu size={20} /></button>
        </div>
      </header>

      <main>
        <section className="command-deck" aria-labelledby="overview-title">
          <div className="command-deck__story">
            <p className="eyebrow">Global field report · {RANGE_LABELS[filters.timeRange]}</p>
            <h1 id="overview-title">Earth in motion, <span>as it happens.</span></h1>
            {strongest ? (
              <button className="lead-event" type="button" onClick={() => selectEvent(strongest.id)}>
                <span className={`lead-event__mag magnitude-${strongest.magnitude !== null && strongest.magnitude >= 6 ? 'major' : strongest.magnitude !== null && strongest.magnitude >= 5 ? 'strong' : strongest.magnitude !== null && strongest.magnitude >= 4 ? 'moderate' : 'minor'}`}>{formatMagnitude(strongest.magnitude)}</span>
                <span><small>Strongest in view · {magnitudeLabel(strongest.magnitude)}</small><strong>{strongest.place}</strong><em>{formatRelativeTime(strongest.time)} · {significanceLabel(strongest.significance)}</em></span>
                <ChevronDown size={18} aria-hidden="true" />
              </button>
            ) : <p className="command-deck__empty-lead">No event currently matches every active constraint.</p>}
          </div>
          <div className="command-deck__metrics" aria-label="Current activity summary">
            <div><span>Matching</span><strong>{filteredEvents.length.toLocaleString()}</strong><small>of {events.length.toLocaleString()} loaded</small></div>
            <div><span>Magnitude 4+</span><strong>{filteredEvents.filter((event) => (event.magnitude ?? 0) >= 4).length.toLocaleString()}</strong><small>notable energy release</small></div>
            <div><span>Shallow</span><strong>{filteredEvents.filter((event) => event.depth <= 70).length.toLocaleString()}</strong><small>70 km deep or less</small></div>
          </div>
        </section>

        <section className="controls" aria-label="Earthquake search and controls">
          <div className="segmented time-selector" aria-label="Time range">
            {RANGE_OPTIONS.map((range) => <button key={range} type="button" className={filters.timeRange === range ? 'is-active' : ''} aria-pressed={filters.timeRange === range} onClick={() => setFilters((current) => ({ ...current, timeRange: range }))}>{RANGE_LABELS[range]}</button>)}
          </div>
          <label className="search-field">
            <Search size={17} aria-hidden="true" />
            <span className="sr-only">Search loaded places or regions</span>
            <input type="search" value={filters.query} placeholder="Search loaded places or regions" onChange={(event) => setFilters((current) => ({ ...current, query: event.target.value }))} />
            {filters.query && <button type="button" onClick={() => setFilters((current) => ({ ...current, query: '' }))} aria-label="Clear place search"><X size={15} /></button>}
          </label>
          <label className="select-field"><Globe2 size={17} aria-hidden="true" /><span className="sr-only">Geographic area</span><select value={filters.area} onChange={(event) => setFilters((current) => ({ ...current, area: event.target.value as GeoArea }))}>{AREA_OPTIONS.map((area) => <option key={area} value={area}>{AREA_LABELS[area]}</option>)}</select><ChevronDown size={15} aria-hidden="true" /></label>
          <label className="select-field sort-field"><span className="sr-only">Sort earthquake events</span><select value={filters.sort} onChange={(event) => setFilters((current) => ({ ...current, sort: event.target.value as SortMode }))}>{SORT_OPTIONS.map((option) => <option key={option.value} value={option.value}>{option.label}</option>)}</select><ChevronDown size={15} aria-hidden="true" /></label>
          <button className={`button button--filter${activeCount ? ' is-active' : ''}`} type="button" onClick={() => setFiltersOpen(true)} aria-expanded={filtersOpen}><SlidersHorizontal size={17} /> Filters {activeCount > 0 && <span>{activeCount}</span>}</button>
          {activeCount > 0 && <button className="button button--reset" type="button" onClick={resetFilters}><RotateCcw size={16} /> Reset</button>}
        </section>
        {activeCount > 0 && (
          <div className="active-filters" aria-label="Active filters">
            <span>Active field</span>
            {filters.minMagnitude !== DEFAULT_FILTERS.minMagnitude && <button type="button" onClick={() => setFilters((current) => ({ ...current, minMagnitude: DEFAULT_FILTERS.minMagnitude }))}>M {filters.minMagnitude.toFixed(1)}+ <X size={12} /></button>}
            {filters.maxDepth !== DEFAULT_FILTERS.maxDepth && <button type="button" onClick={() => setFilters((current) => ({ ...current, maxDepth: DEFAULT_FILTERS.maxDepth }))}>≤ {filters.maxDepth} km <X size={12} /></button>}
            {filters.alerts.length > 0 && <button type="button" onClick={() => setFilters((current) => ({ ...current, alerts: [] }))}>{filters.alerts.join(', ')} alerts <X size={12} /></button>}
            {filters.tsunamiOnly && <button type="button" onClick={() => setFilters((current) => ({ ...current, tsunamiOnly: false }))}>Tsunami flag <X size={12} /></button>}
            {filters.reviewStatus !== 'all' && <button type="button" onClick={() => setFilters((current) => ({ ...current, reviewStatus: 'all' }))}>{filters.reviewStatus} <X size={12} /></button>}
            {filters.area !== 'world' && <button type="button" onClick={() => setFilters((current) => ({ ...current, area: 'world' }))}>{AREA_LABELS[filters.area]} <X size={12} /></button>}
            {filters.query.trim() && <button type="button" onClick={() => setFilters((current) => ({ ...current, query: '' }))}>“{filters.query.trim()}” <X size={12} /></button>}
          </div>
        )}

        {(error || isOffline || isStale) && events.length > 0 && (
          <div className={`data-banner${error ? ' data-banner--error' : ''}`} role="status">
            {isOffline ? <WifiOff size={18} /> : error ? <AlertCircle size={18} /> : <RefreshCw size={18} />}
            <div><strong>{isOffline ? 'You are offline' : error ? 'Live refresh failed' : 'Displayed data may be stale'}</strong><span>Showing preserved USGS data received {receivedAt ? formatRelativeTime(receivedAt) : 'earlier'}. Filters and selection remain available.</span></div>
            <button type="button" onClick={() => void refresh()}>Retry</button>
          </div>
        )}

        {loading ? <LoadingSkeleton /> : error && events.length === 0 ? (
          <div className="fatal-state" role="alert">
            <AlertCircle size={30} />
            <p className="eyebrow">USGS connection unavailable</p>
            <h2>Live earthquake data could not be reached</h2>
            <p>{error} No fictional data has been substituted. Check your connection, then try again.</p>
            <button className="button button--primary" type="button" onClick={() => void refresh()}><RefreshCw size={17} /> Retry live data</button>
          </div>
        ) : (
          <>
            <div className="mobile-view-switcher segmented" aria-label="Mobile content view">
              <button type="button" className={mobileView === 'map' ? 'is-active' : ''} onClick={() => setMobileView('map')}>Map</button>
              <button type="button" className={mobileView === 'stream' ? 'is-active' : ''} onClick={() => setMobileView('stream')}>Event stream</button>
            </div>
            <section className={`atlas ${mobileView === 'stream' ? 'show-stream' : 'show-map'}`} aria-label="Synchronized earthquake map and event stream">
              <div className="atlas__map">
                <EarthquakeMap events={filteredEvents} selectedId={selectedId} hoveredId={hoveredId} onSelect={selectEvent} onHover={setHoveredId} onBoundsChange={setBounds} fitNonce={fitNonce} />
                <div className="map-toolbar">
                  <button type="button" onClick={() => setFitNonce((value) => value + 1)}><Crosshair size={16} /> Fit events</button>
                  <button type="button" onClick={() => setFilters((current) => ({ ...current, area: current.area === 'viewport' ? 'world' : 'viewport' }))} className={filters.area === 'viewport' ? 'is-active' : ''} aria-pressed={filters.area === 'viewport'}><LocateFixed size={16} /> {filters.area === 'viewport' ? 'Following map' : 'Filter to map'}</button>
                </div>
              </div>
              <div className="atlas__stream" id="event-stream">
                {filteredEvents.length > 0 ? <EventStream events={filteredEvents} selectedId={selectedId} hoveredId={hoveredId} onSelect={selectEvent} onHover={setHoveredId} /> : (
                  <div className="empty-state">
                    <Filter size={28} />
                    <p className="eyebrow">No events in this field</p>
                    <h2>Your filters leave no earthquakes to show</h2>
                    <p>Try lowering the minimum magnitude, increasing depth, choosing a wider area, or clearing the place search.</p>
                    <button className="button button--primary" type="button" onClick={resetFilters}><RotateCcw size={17} /> Reset filters</button>
                  </div>
                )}
              </div>
            </section>
            <SeismicTimeline events={filteredEvents} selectedId={selectedId} hoveredId={hoveredId} onSelect={selectEvent} onHover={setHoveredId} />
          </>
        )}
      </main>

      {selected && <EventDetail event={selected} onClose={() => setSelectedId(null)} onShare={() => void share()} />}
      {filtersOpen && <div className="filter-overlay" role="dialog" aria-modal="true" aria-label="Earthquake filters" onMouseDown={(event) => { if (event.target === event.currentTarget) setFiltersOpen(false) }}><FilterPanel filters={filters} setFilters={setFilters} onReset={resetFilters} count={activeCount} onClose={() => setFiltersOpen(false)} /></div>}
      {toast && <div className="toast" role="status"><Check size={16} /> {toast}</div>}
      <div className="sr-only" aria-live="polite">{refreshing ? 'Refreshing earthquake data.' : `${filteredEvents.length} earthquake events match the current filters.`}{selected ? ` Selected magnitude ${formatMagnitude(selected.magnitude)} near ${selected.place}.` : ''}</div>
      <footer className="site-footer"><span>Live data: <a href="https://earthquake.usgs.gov/" target="_blank" rel="noreferrer">U.S. Geological Survey</a></span><span>Data is preliminary and may be revised. This product does not predict earthquakes or guarantee safety.</span></footer>
    </div>
  )
}

import { useEffect, useRef } from 'react'
import L from 'leaflet'
import 'leaflet/dist/leaflet.css'
import 'leaflet.markercluster'
import 'leaflet.markercluster/dist/MarkerCluster.css'
import 'leaflet.markercluster/dist/MarkerCluster.Default.css'
import { depthClass, formatMagnitude, formatRelativeTime, magnitudeBand } from '../lib/earthquakes'
import type { Earthquake, MapBounds } from '../types/earthquake'

interface EarthquakeMapProps {
  events: Earthquake[]
  selectedId: string | null
  hoveredId: string | null
  onSelect: (id: string) => void
  onHover: (id: string | null) => void
  onBoundsChange: (bounds: MapBounds) => void
  fitNonce: number
}

function markerHtml(event: Earthquake, selected: boolean, hovered: boolean): string {
  const mag = event.magnitude ?? 0
  const size = Math.max(24, Math.min(58, 18 + mag * 6))
  const band = magnitudeBand(event.magnitude)
  const depth = depthClass(event.depth)
  return `<button class="quake-marker quake-marker--${band} quake-marker--${depth}${selected ? ' is-selected' : ''}${hovered ? ' is-hovered' : ''}" style="--marker-size:${size}px" aria-label="Magnitude ${formatMagnitude(event.magnitude)}, ${event.place}"><span>${formatMagnitude(event.magnitude)}</span></button>`
}

export function EarthquakeMap({ events, selectedId, hoveredId, onSelect, onHover, onBoundsChange, fitNonce }: EarthquakeMapProps) {
  const containerRef = useRef<HTMLDivElement>(null)
  const mapRef = useRef<L.Map | null>(null)
  const clusterRef = useRef<L.MarkerClusterGroup | null>(null)
  const markersRef = useRef(new Map<string, L.Marker>())
  const callbacksRef = useRef({ onSelect, onHover, onBoundsChange })
  const lastFitNonceRef = useRef(fitNonce)

  callbacksRef.current = { onSelect, onHover, onBoundsChange }

  useEffect(() => {
    if (!containerRef.current || mapRef.current) return
    const map = L.map(containerRef.current, {
      center: [18, 0],
      zoom: 2,
      minZoom: 2,
      worldCopyJump: true,
      zoomControl: false,
      preferCanvas: true,
    })
    L.tileLayer('https://{s}.basemaps.cartocdn.com/dark_all/{z}/{x}/{y}{r}.png', {
      attribution: '&copy; OpenStreetMap contributors &copy; CARTO',
      subdomains: 'abcd',
      maxZoom: 19,
    }).addTo(map)
    L.control.zoom({ position: 'bottomright' }).addTo(map)
    const clusters = L.markerClusterGroup({
      showCoverageOnHover: false,
      spiderfyOnMaxZoom: true,
      removeOutsideVisibleBounds: true,
      maxClusterRadius: 44,
      iconCreateFunction: (cluster) => {
        const count = cluster.getChildCount()
        return L.divIcon({
          className: 'quake-cluster-wrap',
          html: `<button class="quake-cluster" aria-label="${count} earthquakes grouped. Zoom to inspect"><span>${count}</span><small>events</small></button>`,
          iconSize: L.point(54, 54),
        })
      },
    })
    clusters.addTo(map)
    const announceBounds = () => {
      const bounds = map.getBounds()
      callbacksRef.current.onBoundsChange({ north: bounds.getNorth(), south: bounds.getSouth(), east: bounds.getEast(), west: bounds.getWest() })
    }
    map.on('moveend', announceBounds)
    announceBounds()
    mapRef.current = map
    clusterRef.current = clusters
    window.setTimeout(() => map.invalidateSize(), 0)
    return () => {
      map.off('moveend', announceBounds)
      map.remove()
      mapRef.current = null
      clusterRef.current = null
      markersRef.current.clear()
    }
  }, [])

  useEffect(() => {
    const cluster = clusterRef.current
    if (!cluster) return
    cluster.clearLayers()
    markersRef.current.clear()
    const markers = events.map((event) => {
      const marker = L.marker([event.latitude, event.longitude], {
        icon: L.divIcon({
          className: 'quake-marker-wrap',
          html: markerHtml(event, event.id === selectedId, event.id === hoveredId),
          iconSize: undefined,
          iconAnchor: undefined,
        }),
        title: `M ${formatMagnitude(event.magnitude)} — ${event.place}`,
        keyboard: true,
        riseOnHover: true,
      })
      marker.bindTooltip(`<strong>M ${formatMagnitude(event.magnitude)}</strong><br>${event.place}<br><span>${formatRelativeTime(event.time)} · ${Math.round(event.depth)} km deep</span>`, {
        className: 'quake-tooltip', direction: 'top', offset: [0, -12], opacity: 1,
      })
      marker.on('click', () => callbacksRef.current.onSelect(event.id))
      marker.on('mouseover focus', () => callbacksRef.current.onHover(event.id))
      marker.on('mouseout blur', () => callbacksRef.current.onHover(null))
      markersRef.current.set(event.id, marker)
      return marker
    })
    cluster.addLayers(markers)
  }, [events, selectedId, hoveredId])

  useEffect(() => {
    const map = mapRef.current
    const cluster = clusterRef.current
    if (!map || !cluster || !selectedId) return
    const marker = markersRef.current.get(selectedId)
    if (!marker) return
    cluster.zoomToShowLayer(marker, () => {
      map.panTo(marker.getLatLng(), { animate: !window.matchMedia('(prefers-reduced-motion: reduce)').matches })
      marker.openTooltip()
    })
  }, [selectedId])

  useEffect(() => {
    const map = mapRef.current
    if (!map || fitNonce === lastFitNonceRef.current) return
    lastFitNonceRef.current = fitNonce
    if (events.length === 0) return
    const bounds = L.latLngBounds(events.map((event) => [event.latitude, event.longitude] as [number, number]))
    map.fitBounds(bounds, { padding: [48, 48], maxZoom: 6 })
  }, [fitNonce, events])

  return (
    <div className="map-shell">
      <div ref={containerRef} className="earthquake-map" aria-label="Interactive map of filtered earthquake events" />
      <div className="map-key" aria-label="Map marker legend">
        <span><i className="key-dot key-dot--minor" /> Under 4</span>
        <span><i className="key-dot key-dot--moderate" /> 4–4.9</span>
        <span><i className="key-dot key-dot--strong" /> 5–5.9</span>
        <span><i className="key-dot key-dot--major" /> 6+</span>
        <span className="map-key__depth">Ring thickness indicates depth</span>
      </div>
    </div>
  )
}

import { useMemo, useState } from 'react'
import { formatMagnitude, formatRelativeTime } from '../lib/earthquakes'
import type { Earthquake } from '../types/earthquake'

interface SeismicTimelineProps {
  events: Earthquake[]
  selectedId: string | null
  hoveredId: string | null
  onSelect: (id: string) => void
  onHover: (id: string | null) => void
}

const WIDTH = 1000
const HEIGHT = 152
const PAD_X = 16
const PAD_Y = 18

export function SeismicTimeline({ events, selectedId, hoveredId, onSelect, onHover }: SeismicTimelineProps) {
  const [cursor, setCursor] = useState(1000)
  const ordered = useMemo(() => [...events].sort((a, b) => a.time - b.time), [events])
  const minTime = ordered[0]?.time ?? Date.now() - 1
  const maxTime = ordered.at(-1)?.time ?? Date.now()
  const duration = Math.max(1, maxTime - minTime)
  const points = useMemo(() => ordered.map((event) => ({
    event,
    x: PAD_X + ((event.time - minTime) / duration) * (WIDTH - PAD_X * 2),
    y: HEIGHT - PAD_Y - Math.min(1, Math.max(0, (event.magnitude ?? 0) / 8)) * (HEIGHT - PAD_Y * 2),
    r: Math.max(2.5, Math.min(8, 2 + (event.magnitude ?? 0) * 0.65)),
  })), [ordered, minTime, duration])
  const nearest = ordered.length ? ordered.reduce((best, event) => {
    const target = minTime + (cursor / 1000) * duration
    return Math.abs(event.time - target) < Math.abs(best.time - target) ? event : best
  }, ordered[0]) : null
  const strongest = ordered.reduce<Earthquake | null>((best, event) => !best || (event.magnitude ?? -1) > (best.magnitude ?? -1) ? event : best, null)

  return (
    <section className="timeline" aria-labelledby="timeline-title">
      <header className="timeline__header">
        <div>
          <p className="eyebrow">Connected seismic timeline</p>
          <h2 id="timeline-title">Activity through time</h2>
        </div>
        <p className="timeline__instruction">Scrub to trace an event across the map and stream.</p>
      </header>
      {events.length > 0 ? (
        <>
          <div className="timeline__plot">
            <svg viewBox={`0 0 ${WIDTH} ${HEIGHT}`} role="img" aria-labelledby="timeline-chart-title timeline-chart-desc" preserveAspectRatio="none">
              <title id="timeline-chart-title">Earthquake activity by time and magnitude</title>
              <desc id="timeline-chart-desc">Each point is one earthquake. Position from left to right shows time; height and size show magnitude. {strongest ? `The strongest shown is magnitude ${formatMagnitude(strongest.magnitude)} near ${strongest.place}.` : ''}</desc>
              <line x1={PAD_X} y1={HEIGHT - PAD_Y} x2={WIDTH - PAD_X} y2={HEIGHT - PAD_Y} className="timeline__baseline" />
              {[2, 4, 6].map((magnitude) => {
                const y = HEIGHT - PAD_Y - (magnitude / 8) * (HEIGHT - PAD_Y * 2)
                return <line key={magnitude} x1={PAD_X} y1={y} x2={WIDTH - PAD_X} y2={y} className="timeline__guide" />
              })}
              <path className="timeline__trace" d={points.map((point, index) => `${index === 0 ? 'M' : 'L'} ${point.x} ${point.y}`).join(' ')} />
              {points.map(({ event, x, y, r }) => (
                <circle
                  key={event.id}
                  cx={x}
                  cy={y}
                  r={event.id === selectedId ? r + 3 : event.id === hoveredId ? r + 2 : r}
                  className={`timeline__point magnitude-${event.magnitude !== null && event.magnitude >= 6 ? 'major' : event.magnitude !== null && event.magnitude >= 5 ? 'strong' : event.magnitude !== null && event.magnitude >= 4 ? 'moderate' : 'minor'}${event.id === selectedId ? ' is-selected' : ''}`}
                  tabIndex={0}
                  role="button"
                  aria-label={`Magnitude ${formatMagnitude(event.magnitude)}, ${event.place}, ${formatRelativeTime(event.time)}`}
                  onMouseEnter={() => onHover(event.id)}
                  onMouseLeave={() => onHover(null)}
                  onFocus={() => onHover(event.id)}
                  onBlur={() => onHover(null)}
                  onClick={() => onSelect(event.id)}
                  onKeyDown={(keyEvent) => {
                    if (keyEvent.key === 'Enter' || keyEvent.key === ' ') {
                      keyEvent.preventDefault()
                      onSelect(event.id)
                    }
                  }}
                />
              ))}
              <line x1={PAD_X + (cursor / 1000) * (WIDTH - PAD_X * 2)} y1="5" x2={PAD_X + (cursor / 1000) * (WIDTH - PAD_X * 2)} y2={HEIGHT - 5} className="timeline__cursor" />
            </svg>
            <input
              className="timeline__scrubber"
              type="range"
              min="0"
              max="1000"
              value={cursor}
              aria-label="Scrub through earthquake activity in time"
              aria-valuetext={nearest ? `${formatRelativeTime(nearest.time)}: magnitude ${formatMagnitude(nearest.magnitude)} near ${nearest.place}` : 'No event'}
              onChange={(event) => {
                const next = Number(event.target.value)
                setCursor(next)
                if (!ordered.length) return
                const target = minTime + (next / 1000) * duration
                const closest = ordered.reduce((best, item) => Math.abs(item.time - target) < Math.abs(best.time - target) ? item : best, ordered[0])
                onHover(closest.id)
              }}
              onPointerUp={() => nearest && onSelect(nearest.id)}
              onKeyUp={() => nearest && onSelect(nearest.id)}
            />
          </div>
          <div className="timeline__labels" aria-hidden="true">
            <span>{formatRelativeTime(minTime)}</span>
            <span>Now</span>
          </div>
          <p className="sr-only" aria-live="polite">{nearest ? `Timeline cursor: ${nearest.place}, magnitude ${formatMagnitude(nearest.magnitude)}, ${formatRelativeTime(nearest.time)}.` : ''}</p>
        </>
      ) : <div className="timeline__empty">No events to plot for the current filters.</div>}
    </section>
  )
}

import { useCallback, useEffect, useRef, useState } from 'react'
import { FEED_URLS, parseCollection } from '../lib/earthquakes'
import type { Earthquake, TimeRange } from '../types/earthquake'

interface EarthquakeDataState {
  events: Earthquake[]
  generatedAt: number | null
  receivedAt: number | null
  loading: boolean
  refreshing: boolean
  error: string | null
}

const CACHE_KEY = 'tectonic:last-data'

function readCache(): Pick<EarthquakeDataState, 'events' | 'generatedAt' | 'receivedAt'> | null {
  try {
    const raw = localStorage.getItem(CACHE_KEY)
    if (!raw) return null
    const cached = JSON.parse(raw) as Pick<EarthquakeDataState, 'events' | 'generatedAt' | 'receivedAt'>
    return Array.isArray(cached.events) ? cached : null
  } catch {
    return null
  }
}

export function useEarthquakeData(timeRange: TimeRange) {
  const [state, setState] = useState<EarthquakeDataState>(() => {
    const cached = readCache()
    return {
      events: cached?.events ?? [],
      generatedAt: cached?.generatedAt ?? null,
      receivedAt: cached?.receivedAt ?? null,
      loading: !cached,
      refreshing: false,
      error: null,
    }
  })
  const requestRef = useRef<AbortController | null>(null)
  const firstLoadRef = useRef(true)

  const load = useCallback(async (background = false) => {
    requestRef.current?.abort()
    const controller = new AbortController()
    requestRef.current = controller
    setState((current) => ({
      ...current,
      loading: !background && current.events.length === 0,
      refreshing: background || current.events.length > 0,
      error: null,
    }))

    try {
      const response = await fetch(FEED_URLS[timeRange], {
        signal: controller.signal,
        headers: { Accept: 'application/geo+json, application/json' },
      })
      if (!response.ok) throw new Error(`USGS request failed with status ${response.status}.`)
      const parsed = parseCollection(await response.json())
      const receivedAt = Date.now()
      const next = { ...parsed, receivedAt }
      try {
        localStorage.setItem(CACHE_KEY, JSON.stringify(next))
      } catch {
        // Large 30-day feeds can exceed storage quotas; live data remains available in memory.
      }
      setState({ ...next, loading: false, refreshing: false, error: null })
    } catch (error) {
      if (controller.signal.aborted) return
      setState((current) => ({
        ...current,
        loading: false,
        refreshing: false,
        error: error instanceof Error ? error.message : 'Live USGS data could not be loaded.',
      }))
    }
  }, [timeRange])

  useEffect(() => {
    const hasData = state.events.length > 0
    void load(hasData && firstLoadRef.current)
    firstLoadRef.current = false
    return () => requestRef.current?.abort()
    // state.events is intentionally excluded: loading should follow time-range changes only.
  }, [load])

  useEffect(() => {
    const refresh = () => void load(true)
    const interval = window.setInterval(refresh, 5 * 60_000)
    const onOnline = () => refresh()
    window.addEventListener('online', onOnline)
    return () => {
      window.clearInterval(interval)
      window.removeEventListener('online', onOnline)
    }
  }, [load])

  return { ...state, refresh: () => load(true) }
}

import type { Earthquake, FilterState, GeoArea, MapBounds, TimeRange, UsgsFeature, UsgsFeatureCollection } from '../types/earthquake'

export const FEED_URLS: Record<TimeRange, string> = {
  hour: 'https://earthquake.usgs.gov/earthquakes/feed/v1.0/summary/all_hour.geojson',
  day: 'https://earthquake.usgs.gov/earthquakes/feed/v1.0/summary/all_day.geojson',
  week: 'https://earthquake.usgs.gov/earthquakes/feed/v1.0/summary/all_week.geojson',
  month: 'https://earthquake.usgs.gov/earthquakes/feed/v1.0/summary/all_month.geojson',
}

export const RANGE_LABELS: Record<TimeRange, string> = {
  hour: 'Past hour', day: 'Past day', week: '7 days', month: '30 days',
}

export const AREA_LABELS: Record<GeoArea, string> = {
  world: 'Worldwide', americas: 'Americas', pacific: 'Pacific Ring', asia: 'Asia',
  europe: 'Europe', africa: 'Africa', oceania: 'Oceania', viewport: 'Visible map',
}

export const DEFAULT_FILTERS: FilterState = {
  timeRange: 'day',
  minMagnitude: 1,
  maxDepth: 700,
  alerts: [],
  tsunamiOnly: false,
  reviewStatus: 'all',
  area: 'world',
  query: '',
  sort: 'significance',
}

export function normalizeFeature(feature: UsgsFeature): Earthquake {
  const [longitude, latitude, depth] = feature.geometry.coordinates
  const p = feature.properties
  return {
    id: feature.id,
    magnitude: p.mag,
    place: p.place || 'Location not reported',
    time: p.time,
    updated: p.updated,
    longitude,
    latitude,
    depth,
    felt: p.felt,
    cdi: p.cdi,
    mmi: p.mmi,
    alert: p.alert,
    status: p.status,
    tsunami: p.tsunami === 1,
    significance: p.sig,
    network: p.net,
    code: p.code,
    magnitudeType: p.magType,
    eventType: p.type,
    title: p.title,
    url: p.url,
    detailUrl: p.detail,
  }
}

export function parseCollection(value: unknown): { events: Earthquake[]; generatedAt: number } {
  if (!value || typeof value !== 'object') throw new Error('USGS returned an unreadable response.')
  const collection = value as UsgsFeatureCollection
  if (!Array.isArray(collection.features) || !collection.metadata?.generated) {
    throw new Error('USGS returned an unexpected data format.')
  }
  return { events: collection.features.map(normalizeFeature), generatedAt: collection.metadata.generated }
}

function inArea(event: Earthquake, area: GeoArea, bounds: MapBounds | null): boolean {
  const { latitude: lat, longitude: lon } = event
  if (area === 'world') return true
  if (area === 'viewport') {
    if (!bounds) return true
    const longitudeMatch = bounds.west <= bounds.east
      ? lon >= bounds.west && lon <= bounds.east
      : lon >= bounds.west || lon <= bounds.east
    return lat >= bounds.south && lat <= bounds.north && longitudeMatch
  }
  if (area === 'americas') return lat >= -60 && lat <= 85 && lon >= -170 && lon <= -30
  if (area === 'pacific') return (lon >= 120 || lon <= -65) && lat >= -60 && lat <= 70
  if (area === 'asia') return lat >= -10 && lat <= 80 && lon >= 25 && lon <= 180
  if (area === 'europe') return lat >= 34 && lat <= 72 && lon >= -25 && lon <= 45
  if (area === 'africa') return lat >= -38 && lat <= 38 && lon >= -20 && lon <= 55
  return lat >= -55 && lat <= 10 && (lon >= 105 || lon <= -110)
}

export function filterAndSort(events: Earthquake[], filters: FilterState, bounds: MapBounds | null): Earthquake[] {
  const query = filters.query.trim().toLocaleLowerCase()
  return events
    .filter((event) => (event.magnitude ?? -Infinity) >= filters.minMagnitude)
    .filter((event) => event.depth <= filters.maxDepth)
    .filter((event) => filters.alerts.length === 0 || filters.alerts.includes(event.alert ?? 'none'))
    .filter((event) => !filters.tsunamiOnly || event.tsunami)
    .filter((event) => filters.reviewStatus === 'all' || (filters.reviewStatus === 'reviewed' ? event.status === 'reviewed' : event.status !== 'reviewed'))
    .filter((event) => inArea(event, filters.area, bounds))
    .filter((event) => !query || `${event.place} ${event.title} ${event.network}`.toLocaleLowerCase().includes(query))
    .sort((a, b) => {
      if (filters.sort === 'newest') return b.time - a.time
      if (filters.sort === 'magnitude') return (b.magnitude ?? -1) - (a.magnitude ?? -1)
      if (filters.sort === 'depth') return b.depth - a.depth
      if (filters.sort === 'felt') return (b.felt ?? -1) - (a.felt ?? -1)
      return b.significance - a.significance || (b.magnitude ?? -1) - (a.magnitude ?? -1)
    })
}

export function magnitudeBand(magnitude: number | null): 'minor' | 'light' | 'moderate' | 'strong' | 'major' | 'unknown' {
  if (magnitude === null) return 'unknown'
  if (magnitude >= 6) return 'major'
  if (magnitude >= 5) return 'strong'
  if (magnitude >= 4) return 'moderate'
  if (magnitude >= 2.5) return 'light'
  return 'minor'
}

export function magnitudeLabel(magnitude: number | null): string {
  if (magnitude === null) return 'Magnitude pending'
  const band = magnitudeBand(magnitude)
  return `${band.charAt(0).toUpperCase()}${band.slice(1)} magnitude`
}

export function formatMagnitude(magnitude: number | null): string {
  return magnitude === null ? '—' : magnitude.toFixed(1)
}

export function formatDepth(depth: number): string {
  return `${depth < 10 ? depth.toFixed(1) : Math.round(depth)} km`
}

export function formatRelativeTime(time: number, now = Date.now()): string {
  const minutes = Math.max(0, Math.floor((now - time) / 60_000))
  if (minutes < 1) return 'Just now'
  if (minutes < 60) return `${minutes}m ago`
  const hours = Math.floor(minutes / 60)
  if (hours < 24) return `${hours}h ${minutes % 60}m ago`
  const days = Math.floor(hours / 24)
  return `${days}d ${hours % 24}h ago`
}

export function formatDateTime(time: number): string {
  return new Intl.DateTimeFormat(undefined, {
    dateStyle: 'medium', timeStyle: 'long',
  }).format(new Date(time))
}

export function formatUtc(time: number): string {
  return new Intl.DateTimeFormat('en', {
    timeZone: 'UTC', month: 'short', day: 'numeric', year: 'numeric',
    hour: '2-digit', minute: '2-digit', second: '2-digit', hour12: false,
  }).format(new Date(time)) + ' UTC'
}

export function significanceLabel(value: number): string {
  if (value >= 600) return 'Highly significant'
  if (value >= 400) return 'Notable'
  if (value >= 250) return 'Above ordinary'
  return 'Routine activity'
}

export function depthClass(depth: number): 'shallow' | 'intermediate' | 'deep' {
  if (depth <= 70) return 'shallow'
  if (depth <= 300) return 'intermediate'
  return 'deep'
}

export function filterCount(filters: FilterState): number {
  return Number(filters.minMagnitude !== DEFAULT_FILTERS.minMagnitude)
    + Number(filters.maxDepth !== DEFAULT_FILTERS.maxDepth)
    + Number(filters.alerts.length > 0)
    + Number(filters.tsunamiOnly)
    + Number(filters.reviewStatus !== 'all')
    + Number(filters.area !== 'world')
    + Number(Boolean(filters.query.trim()))
}

export function filtersFromUrl(): { filters: FilterState; selectedId: string | null } {
  const params = new URLSearchParams(window.location.search)
  const timeRange = params.get('range') as TimeRange | null
  const minMagnitudeParam = params.get('minMag')
  const maxDepthParam = params.get('maxDepth')
  const sort = params.get('sort') as FilterState['sort'] | null
  const area = params.get('area') as GeoArea | null
  const review = params.get('review') as FilterState['reviewStatus'] | null
  const alerts = (params.get('alerts')?.split(',') ?? []).filter(Boolean) as FilterState['alerts']
  return {
    filters: {
      ...DEFAULT_FILTERS,
      timeRange: timeRange && timeRange in FEED_URLS ? timeRange : DEFAULT_FILTERS.timeRange,
      minMagnitude: minMagnitudeParam !== null && Number.isFinite(Number(minMagnitudeParam)) ? Number(minMagnitudeParam) : DEFAULT_FILTERS.minMagnitude,
      maxDepth: maxDepthParam !== null && Number.isFinite(Number(maxDepthParam)) ? Number(maxDepthParam) : DEFAULT_FILTERS.maxDepth,
      alerts,
      tsunamiOnly: params.get('tsunami') === '1',
      reviewStatus: review === 'reviewed' || review === 'automatic' ? review : 'all',
      area: area && area in AREA_LABELS ? area : 'world',
      query: params.get('q') ?? '',
      sort: sort && ['significance', 'newest', 'magnitude', 'depth', 'felt'].includes(sort) ? sort : 'significance',
    },
    selectedId: params.get('event'),
  }
}

export function writeUrlState(filters: FilterState, selectedId: string | null): void {
  const params = new URLSearchParams()
  if (filters.timeRange !== DEFAULT_FILTERS.timeRange) params.set('range', filters.timeRange)
  if (filters.minMagnitude !== DEFAULT_FILTERS.minMagnitude) params.set('minMag', String(filters.minMagnitude))
  if (filters.maxDepth !== DEFAULT_FILTERS.maxDepth) params.set('maxDepth', String(filters.maxDepth))
  if (filters.alerts.length) params.set('alerts', filters.alerts.join(','))
  if (filters.tsunamiOnly) params.set('tsunami', '1')
  if (filters.reviewStatus !== 'all') params.set('review', filters.reviewStatus)
  if (filters.area !== 'world') params.set('area', filters.area)
  if (filters.query.trim()) params.set('q', filters.query.trim())
  if (filters.sort !== DEFAULT_FILTERS.sort) params.set('sort', filters.sort)
  if (selectedId) params.set('event', selectedId)
  const next = params.toString() ? `?${params.toString()}` : window.location.pathname
  window.history.replaceState(null, '', next)
}

